-- Dashboards and BI reports: aggregates, rollups, CTE chains
SELECT department_id, COUNT(*) AS headcount, AVG(salary) AS avg_sal, MAX(salary) AS max_sal FROM employees GROUP BY department_id HAVING COUNT(*) > 5 ORDER BY headcount DESC;
SELECT region, product_line, SUM(amount) AS total FROM sales GROUP BY ROLLUP (region, product_line);
SELECT region, product_line, SUM(amount) AS total FROM sales GROUP BY CUBE (region, product_line);
SELECT region, product_line, channel, SUM(amount) AS total, GROUPING(region) AS g_region, GROUPING_ID(region, product_line) AS gid FROM sales GROUP BY GROUPING SETS ((region, product_line), (channel), ());
SELECT TO_CHAR(order_date, 'YYYY-MM') AS month, COUNT(*) AS orders, SUM(total_amount) AS revenue FROM orders WHERE order_date >= ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -12) GROUP BY TO_CHAR(order_date, 'YYYY-MM') ORDER BY 1;
WITH monthly AS (SELECT TRUNC(order_date, 'MM') AS m, SUM(total_amount) AS rev FROM orders GROUP BY TRUNC(order_date, 'MM')) SELECT m, rev, LAG(rev) OVER (ORDER BY m) AS prev_rev, ROUND((rev - LAG(rev) OVER (ORDER BY m)) / NULLIF(LAG(rev) OVER (ORDER BY m), 0) * 100, 2) AS growth_pct FROM monthly ORDER BY m;
WITH dept_totals AS (SELECT department_id, SUM(salary) AS total_sal FROM employees GROUP BY department_id), avg_total AS (SELECT AVG(total_sal) AS avg_sal FROM dept_totals) SELECT d.department_name, dt.total_sal FROM dept_totals dt JOIN departments d ON d.department_id = dt.department_id CROSS JOIN avg_total a WHERE dt.total_sal > a.avg_sal;
WITH a AS (SELECT 1 AS x FROM dual), b AS (SELECT x + 1 AS x FROM a), c AS (SELECT x + 1 AS x FROM b), d AS (SELECT x + 1 AS x FROM c) SELECT * FROM d;
WITH emp_cte (emp_id, mgr_id, lvl) AS (SELECT employee_id, manager_id, 1 FROM employees WHERE manager_id IS NULL UNION ALL SELECT e.employee_id, e.manager_id, c.lvl + 1 FROM employees e JOIN emp_cte c ON e.manager_id = c.emp_id) SELECT * FROM emp_cte;
WITH nums (n) AS (SELECT 1 FROM dual UNION ALL SELECT n + 1 FROM nums WHERE n < 10) SELECT n FROM nums;
SELECT c.customer_id, c.last_name, COUNT(o.order_id) AS order_count, NVL(SUM(o.total_amount), 0) AS lifetime_value FROM customers c LEFT JOIN orders o ON o.customer_id = c.customer_id GROUP BY c.customer_id, c.last_name HAVING NVL(SUM(o.total_amount), 0) > 1000 ORDER BY lifetime_value DESC FETCH FIRST 50 ROWS ONLY;
SELECT p.product_name, c.category_name, s.supplier_name, SUM(oi.quantity) AS units, SUM(oi.quantity * oi.unit_price) AS revenue FROM order_items oi JOIN orders o ON o.order_id = oi.order_id JOIN products p ON p.product_id = oi.product_id JOIN categories c ON c.category_id = p.category_id JOIN suppliers s ON s.supplier_id = p.supplier_id JOIN customers cu ON cu.customer_id = o.customer_id WHERE o.status <> 'CANCELLED' AND cu.country = 'US' GROUP BY p.product_name, c.category_name, s.supplier_name ORDER BY revenue DESC;
SELECT * FROM customers c WHERE EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.customer_id AND o.total_amount > 500) AND NOT EXISTS (SELECT 1 FROM returns r WHERE r.customer_id = c.customer_id);
SELECT department_id, (SELECT MAX(salary) FROM employees e2 WHERE e2.department_id = e.department_id) AS max_sal FROM employees e GROUP BY department_id;
SELECT * FROM employees WHERE salary > ALL (SELECT salary FROM employees WHERE department_id = 30);
SELECT * FROM employees WHERE salary > ANY (SELECT salary FROM employees WHERE department_id = 30);
SELECT * FROM employees WHERE (department_id, job_id) IN (SELECT department_id, job_id FROM job_history);
SELECT employee_id FROM employees MINUS SELECT employee_id FROM terminated_employees;
SELECT employee_id FROM employees INTERSECT SELECT employee_id FROM badges;
SELECT city FROM offices UNION SELECT city FROM warehouses UNION ALL SELECT city FROM stores ORDER BY 1;
SELECT d.department_name, e.cnt FROM departments d, (SELECT department_id, COUNT(*) cnt FROM employees GROUP BY department_id) e WHERE d.department_id = e.department_id(+);
SELECT e.last_name, d.department_name, l.city FROM employees e, departments d, locations l WHERE e.department_id = d.department_id(+) AND d.location_id = l.location_id(+) AND e.salary > 5000;
SELECT e.last_name, m.last_name AS manager FROM employees e, employees m WHERE e.manager_id = m.employee_id (+);
SELECT s.*, d.* FROM sales s INNER JOIN dim_date d ON s.date_key = d.date_key LEFT OUTER JOIN dim_store st ON s.store_key = st.store_key FULL OUTER JOIN dim_promo p ON s.promo_key = p.promo_key;
SELECT * FROM employees e JOIN departments d USING (department_id);
SELECT * FROM employees NATURAL JOIN departments;
SELECT d.department_name, e.last_name FROM departments d CROSS APPLY (SELECT * FROM employees e WHERE e.department_id = d.department_id ORDER BY salary DESC FETCH FIRST 3 ROWS ONLY) e;
SELECT d.department_name, e.last_name FROM departments d, LATERAL (SELECT * FROM employees e WHERE e.department_id = d.department_id) e;
SELECT d.department_name, e.last_name FROM departments d OUTER APPLY (SELECT last_name FROM employees e WHERE e.department_id = d.department_id FETCH FIRST 1 ROW ONLY) e;
SELECT CASE WHEN salary < 3000 THEN 'LOW' WHEN salary < 8000 THEN 'MID' ELSE 'HIGH' END AS band, COUNT(*) FROM employees GROUP BY CASE WHEN salary < 3000 THEN 'LOW' WHEN salary < 8000 THEN 'MID' ELSE 'HIGH' END;
SELECT SUM(CASE WHEN status = 'PAID' THEN 1 ELSE 0 END) AS paid, SUM(CASE WHEN status = 'NEW' THEN 1 ELSE 0 END) AS new_cnt FROM orders;
SELECT COUNT(DISTINCT customer_id) FROM orders WHERE order_date > SYSDATE - 90;
SELECT ROUND(AVG(total_amount), 2) AS avg_order, MEDIAN(total_amount) AS med, STDDEV(total_amount) AS sd, VARIANCE(total_amount) AS var FROM orders;
SELECT PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY salary) AS median_sal, PERCENTILE_DISC(0.9) WITHIN GROUP (ORDER BY salary) AS p90 FROM employees;
SELECT department_id, LISTAGG(last_name, ', ') WITHIN GROUP (ORDER BY last_name) AS names FROM employees GROUP BY department_id;
SELECT LISTAGG(DISTINCT city, ';') WITHIN GROUP (ORDER BY city) FROM customers;
SELECT department_id, LISTAGG(last_name, ', ' ON OVERFLOW TRUNCATE '...' WITH COUNT) WITHIN GROUP (ORDER BY last_name) FROM employees GROUP BY department_id;
